<?php require 'includes/db.php';if($_SERVER['REQUEST_METHOD']!=='POST')redirect('index.php#contact');verify_csrf();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$subject=trim($_POST['subject']??'');$message=trim($_POST['message']??'');if(text_length($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||text_length($subject)<2||text_length($message)<5){flash('danger','Please check your details and try again.');redirect('index.php#contact');}$s=$conn->prepare('INSERT INTO messages(name,email,subject,message) VALUES(?,?,?,?)');$s->bind_param('ssss',$name,$email,$subject,$message);if($s->execute())flash('success','Thank you! Your message has been sent to the J.K BAGS team.');else flash('danger','Your message could not be saved. Please try again.');redirect('index.php#contact');
